class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        for i in 0..<this.data.size() {
            sum += this.data.get(i)
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        var min_val: Float64 = this.data.get(0)
        for i in 1..<this.data.size() {
            if this.data.get(i) < min_val {
                min_val = this.data.get(i)
            }
        }
        return min_val
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        var max_val: Float64 = this.data.get(0)
        for i in 1..<this.data.size() {
            if this.data.get(i) > max_val {
                max_val = this.data.get(i)
            }
        }
        return max_val
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let mean = this.get_sum() / Float64(this.data.size())
        var variance: Float64 = 0.0
        for i in 0..<this.data.size() {
            variance += (this.data.get(i) - mean) * (this.data.get(i) - mean)
        }
        variance = variance / Float64(this.data.size())
        return round(variance * 100) / 100
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        return round(sqrt(this.get_variance()) * 100) / 100
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        // Assuming this method is for self-correlation (which would be 1), 
        // a proper implementation would require a second dataset for true correlation calculation
        return 1.0
    }
}

import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        if data1.size() != data2.size() || data1.isEmpty() {
            return 0.0
        }

        var n = data1.size().toFloat64()
        var sum1 = 0.0
        var sum2 = 0.0
        var sum1_sq = 0.0
        var sum2_sq = 0.0
        var p_sum = 0.0

        for (var i = 0; i < n.toInt(); i++) {
            var x = data1.get(i)
            var y = data2.get(i)
            sum1 += x
            sum2 += y
            sum1_sq += x * x
            sum2_sq += y * y
            p_sum += x * y
        }

        var num = p_sum - (sum1 * sum2 / n)
        var den1 = sqrt((sum1_sq - sum1 * sum1 / n) * (sum2_sq - sum2 * sum2 / n))

        if den1 == 0.0 {
            return 0.0
        }

        return num / den1
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        var n = data.size().toFloat64()
        if n == 0 {
            return 0.0
        }

        var mean = 0.0
        for (var i = 0; i < n.toInt(); i++) {
            mean += data.get(i)
        }
        mean /= n

        var m2 = 0.0
        var m3 = 0.0
        for (var i = 0; i < n.toInt(); i++) {
            var dev = data.get(i) - mean
            var dev_sq = dev * dev
            m2 += dev_sq
            m3 += dev_sq * dev
        }

        if m2 == 0 {
            return 0.0
        }

        m3 = m3 / n
        m2 = m2 / n
        var skew = m3 / (m2 * sqrt(m2))

        var adj_factor = sqrt(n * (n - 1)) / (n - 2)
        return skew * adj_factor
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        var n = data.size().toFloat64()
        if n == 0 {
            return 0.0
        }

        var mean = 0.0
        for (var i = 0; i < n.toInt(); i++) {
            mean += data.get(i)
        }
        mean /= n

        var m2 = 0.0
        var m4 = 0.0
        for (var i = 0; i < n.toInt(); i++) {
            var dev = data.get(i) - mean
            var dev_sq = dev * dev
            m2 += dev_sq
            m4 += dev_sq * dev_sq
        }

        if m2 == 0 {
            return 0.0
        }

        m4 = m4 / n
        m2 = m2 / n
        var kurt = m4 / (m2 * m2) - 3

        var adj_factor = ((n - 1) * (n - 1) * (n - 1)) / (n * (n - 2) * (n - 3))
        var bias_correction = (3 * (n - 1) * (n - 1)) / ((n - 2) * (n - 3))
        return kurt * adj_factor + bias_correction
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        var result = ArrayList<Float64>()
        var inv_sigma_sqrt_2pi = 1.0 / (sigma * sqrt(2 * 3.141592653589793))
        var inv_sigma_sq = 1.0 / (sigma * sigma)

        for (var i = 0; i < data.size(); i++) {
            var x = data.get(i)
            var exponent = -0.5 * (x - mu) * (x - mu) * inv_sigma_sq
            var pdf_value = inv_sigma_sqrt_2pi * exp(exponent)
            result.add(pdf_value)
        }

        return result
    }
}

