import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for xi in x_interp {
            var found = false
            for i in 0..<x.size()-1 {
                if x[i] <= xi && xi <= x[i+1] {
                    let slope = (y[i+1] - y[i]) / (x[i+1] - x[i])
                    let y_val = y[i] + slope * (xi - x[i])
                    result.add(y_val)
                    found = true
                    break
                }
            }
            if !found {
                if xi <= x[0] {
                    result.add(y[0])
                } else {
                    result.add(y[x.size()-1])
                }
            }
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for x_val in x_interp {
            for y_val in y_interp {
                var x_indices = ArrayList<Int>()
                for i in 0..<x.size() {
                    if x[i] <= x_val {
                        x_indices.add(i)
                    }
                }
                if x_indices.size() == 0 {
                    x_indices.add(0)
                }
                let x0 = x_indices[x_indices.size()-1]
                let x1 = if x_indices.size() < x.size() && x_indices[x_indices.size()-1] < x.size()-1 {
                    x_indices[x_indices.size()-1] + 1
                } else {
                    x_indices[x_indices.size()-1]
                }

                var y_indices = ArrayList<Int>()
                for j in 0..<y.size() {
                    if y[j] <= y_val {
                        y_indices.add(j)
                    }
                }
                if y_indices.size() == 0 {
                    y_indices.add(0)
                }
                let y0 = y_indices[y_indices.size()-1]
                let y1 = if y_indices.size() < y.size() && y_indices[y_indices.size()-1] < y.size()-1 {
                    y_indices[y_indices.size()-1] + 1
                } else {
                    y_indices[y_indices.size()-1]
                }

                if x0 == x1 || y0 == y1 {
                    result.add(z[x0][y0])
                    continue
                }

                let z00 = z[x0][y0]
                let z01 = z[x0][y1]
                let z10 = z[x1][y0]
                let z11 = z[x1][y1]

                let x_ratio = (x_val - x[x0]) / (x[x1] - x[x0])
                let y_ratio = (y_val - y[y0]) / (y[y1] - y[y0])

                let top = z00 + x_ratio * (z10 - z00)
                let bottom = z01 + x_ratio * (z11 - z01)
                let z_val = top + y_ratio * (bottom - top)

                result.add(z_val)
            }
        }
        return result
    }
}

import std.convert.Parsable
