class IPAddress {

    /*
    This is a class to process IP Address, including validating, getting the octets and obtaining the binary representation of a valid IP address.
    */

    let ip_address: String

    public init(ip_address: String) {
        /*
        Initialize the IP address to the specified address
        :param ip_address:String
        */
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        /*
        Judge whether the IP address is valid, that is, whether the IP address is composed of four Decimal digits separated by '.'. Each digit is greater than or equal to 0 and less than or equal to 255
        :return: Bool
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.is_valid()
        true
        */
        let pattern = regex("^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$")
        return pattern.is_match(this.ip_address)
    }

    public func get_octets(): ArrayList<String> {
        /*
        If the IP address is valid, the list of four decimal numbers separated by "." constituting the IP address is returned; otherwise, an empty list is returned
        :return: ArrayList<String>
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_octets()
        ["10", "10", "10", "10"]
        */
        if !this.is_valid() {
            return ArrayList()
        }
        return this.ip_address.split(".").to_array_list()
    }

    public func get_binary(): String {
        /*
        If the IP address is valid, return the binary form of the IP address; otherwise, return ''
        :return: String
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_binary()
        "00001010.00001010.00001010.00001010"
        */
        if !this.is_valid() {
            return ""
        }
        let octets = this.get_octets()
        let binary_parts = ArrayList<String>()
        for octet in octets {
            let num = octet.to_int()
            let binary = num.to_binary_string(8)
            binary_parts.add(binary)
        }
        return binary_parts.join(".")
    }
}

import std.net.IPAddress
import std.posix.gethostname
import std.regex

class IpUtil {

    /*
    This is a class as tool for ip that can be used to obtain the local IP address, validate its validity, and also provides the functionality to retrieve the corresponding hostname.
    */

    public static func is_valid_ipv4(ip_address: String): Bool {
        let pattern = regex("^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$")
        return pattern.is_match(ip_address)
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        let pattern = regex("^(([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}|([0-9a-fA-F]{1,4}:){1,7}:|([0-9a-fA-F]{1,4}:){1,6}:[0-9a-fA-F]{1,4}|([0-9a-fA-F]{1,4}:){1,5}(:[0-9a-fA-F]{1,4}){1,2}|([0-9a-fA-F]{1,4}:){1,4}(:[0-9a-fA-F]{1,4}){1,3}|([0-9a-fA-F]{1,4}:){1,3}(:[0-9a-fA-F]{1,4}){1,4}|([0-9a-fA-F]{1,4}:){1,2}(:[0-9a-fA-F]{1,4}){1,5}|[0-9a-fA-F]{1,4}:((:[0-9a-fA-F]{1,4}){1,6})|:((:[0-9a-fA-F]{1,4}){1,7}|:)|fe80:(:[0-9a-fA-F]{0,4}){0,4}%[0-9a-zA-Z]+|::(ffff(:0{1,4})?:)?((25[0-5]|(2[0-4]|1?[0-9])?[0-9])\\.){3}(25[0-5]|(2[0-4]|1?[0-9])?[0-9])|([0-9a-fA-F]{1,4}:){1,4}:((25[0-5]|(2[0-4]|1?[0-9])?[0-9])\\.){3}(25[0-5]|(2[0-4]|1?[0-9])?[0-9]))$")
        return pattern.is_match(ip_address)
    }

    public static func get_hostname(ip_address: String): Option<String> {
        if !is_valid_ipv4(ip_address) && !is_valid_ipv6(ip_address) {
            return None
        }
        let address = try_or_else(() -> IPAddress {
            IPAddress.parse(ip_address)
        }, () -> None)
        if address == None {
            return None
        }
        let hostname = getnameinfo(*address.unwrap(), NI_NAMEREQD)
        if hostname.is_ok() {
            return Some(hostname.unwrap())
        } else {
            return None
        }
    }
}

