        this.resumes.remove(resume)
    }

    public func search_jobs(criteria: String): ArrayList<JobListing> {
        let result = ArrayList<JobListing>()
        for job in this.jobListings {
            for req in job.requirements {
                if req == criteria {
                    result.add(job)
                    break
                }
            }
        }
        return result
    }

    public func get_job_applicants(job: JobListing): ArrayList<Resume> {
        let result = ArrayList<Resume>()
        for resume in this.resumes {
            if JobMarketplace.matches_requirements(resume: resume, requirements: job.requirements) {
                result.add(resume)
            }
        }
        return result
    }

    public static func matches_requirements(resume: Resume, requirements: ArrayList<String>): Bool {
        for req in requirements {
            if !resume.skills.contains(req) {
                return false
            }
        }
        return true
    }
}

import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        if k == 0 {
            return 0.0
        }
        var observedAgreement: Float64 = 0.0
        var diagonalSum: Int64 = 0
        for i in 0..k {
            diagonalSum += testData[i][i]
        }
        var totalSum: Int64 = 0
        for row in testData {
            for val in row {
                totalSum += val
            }
        }
        observedAgreement = Float64(diagonalSum) / Float64(totalSum)

        var expectedAgreement: Float64 = 0.0
        var rowSums: ArrayList<Int64> = ArrayList<Int64>()
        var colSums: ArrayList<Int64> = ArrayList<Int64>()
        for _ in 0..k {
            rowSums.add(0)
            colSums.add(0)
        }
        for i in 0..k {
            var rowSum: Int64 = 0
            for j in 0..k {
                rowSum += testData[i][j]
            }
            rowSums[i] = rowSum
        }
        for j in 0..k {
            var colSum: Int64 = 0
            for i in 0..k {
                colSum += testData[i][j]
            }
            colSums[j] = colSum
        }
        for i in 0..k {
            for j in 0..k {
                expectedAgreement += Float64(rowSums[i]) * Float64(colSums[j])
            }
        }
        expectedAgreement /= Float64(totalSum * totalSum)
        if expectedAgreement == 1.0 {
            return 1.0
        }
        return (observedAgreement - expectedAgreement) / (1.0 - expectedAgreement)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var p_j: ArrayList<Float64> = ArrayList<Float64>()
        for _ in 0..k {
            p_j.add(0.0)
        }
        var totalAssignments: Int64 = 0
        for i in 0..N {
            var rowSum: Int64 = 0
            for j in 0..k {
                rowSum += testData[i][j]
            }
            totalAssignments += rowSum
        }
        if totalAssignments != N * n {
            return 0.0
        }
        for j in 0..k {
            var sum_n_ij: Int64 = 0
            for i in 0..N {
                sum_n_ij += testData[i][j]
            }
            p_j[j] = Float64(sum_n_ij) / Float64(totalAssignments)
        }
        var P_o: Float64 = 0.0
        for i in 0..N {
            var sum_ni_j_sq: Float64 = 0.0
            for j in 0..k {
                sum_ni_j_sq += Float64(testData[i][j]) * Float64(testData[i][j])
            }
            sum_ni_j_sq /= Float64(n * n)
            P_o += sum_ni_j_sq
        }
        P_o /= Float64(N)

        var P_e: Float64 = 0.0
        for j in 0..k {
            P_e += p_j[j] * p_j[j]
        }

        if P_e == 1.0 {
            return 1.0
        }
        return (P_o - P_e) / (1.0 - P_e)
    }
}

import std.collection.ArrayList
import std.regex.Regex

class LongestWord {

    /*
    This is a class allows to add words to a list and find the longest word in a given sentence by comparing the words with the ones in the word list.
    */

    let word_list: ArrayList<String>

    public init() {
        /*
        Initialize a list of word.
        */
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        /*
        append the input word into this.word_list
        :param word: String, input word
        */
        this.word_list.add(word)
    }

    public func find_longest_word(sentence: String): String {
        /*
        Remove punctuation marks and split a sentence into a list of word. Find the longest splited word that is in the this.word_list.
        Words are strictly case sensitive.
        :param sentence: a sentence String
        :return String: longest splited word that is in the this.word_list. return '' if this.word_list is empty.
        >>> longestWord = LongestWord()
        >>> longestWord.add_word('A')
        >>> longestWord.add_word('aM')
        >>> longestWord.find_longest_word('I am a student.')
        'a'
        */
        if this.word_list.size() == 0 {
            return ''
        }
        let regex = Regex("[^a-zA-Z]")
        let cleaned = regex.replace_all(sentence, ' ')
        let words = cleaned.split(' ')
        var longest = ''
        for word in words {
            if word != '' && this.word_list.contains(word) && word.length() > longest.length() {
                longest = word
            }
        }
        return longest
    }
}

import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        var rows: Int64 = BOARD_SIZE.get(0)
        var cols: Int64 = BOARD_SIZE.get(1)
        var new_board: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()
        var random: Random = Random()
        for (var i: Int64 = 0; i < rows; i++) {
            var row: ArrayList<String> = ArrayList<String>()
            for (var j: Int64 = 0; j < cols; j++) {
                var index: Int64 = random.nextInt(ICONS.size())
                row.add(ICONS.get(index))
            }
            new_board.add(row)
        }
        return new_board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        if (pos1 == pos2) {
            return false
        }
        var (x1, y1) = pos1
        var (x2, y2) = pos2
        if (x1 < 0 || x1 >= BOARD_SIZE.get(0) || y1 < 0 || y1 >= BOARD_SIZE.get(1) || x2 < 0 || x2 >= BOARD_SIZE.get(0) || y2 < 0 || y2 >= BOARD_SIZE.get(1)) {
            return false
        }
        if (board.get(x1).get(y1) != board.get(x2).get(y2)) {
            return false
        }
        return has_path(pos1: pos1, pos2: pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        var visited: ArrayList<(Int64, Int64)> = ArrayList<(Int64, Int64)>()
        return bfs_check_path(pos1: pos1, pos2: pos2, visited: visited)
    }

    private func bfs_check_path(pos1: (Int64, Int64), pos2: (Int64, Int64), visited: ArrayList<(Int64, Int64)>): Bool {
        var queue: ArrayList<(Int64, Int64)> = ArrayList<(Int64, Int64)>()
        queue.add(pos1)
        visited.add(pos1)
        var dirs: ArrayList<(Int64, Int64)> = ArrayList<(Int64, Int64)>()
        dirs.add((0, 1))
        dirs.add((1, 0))
        dirs.add((0, -1))
        dirs.add((-1, 0))
        while (!queue.isEmpty()) {
            var current: (Int64, Int64) = queue.remove(0)
            if (current == pos2) {
                return true
            }
            for (var dir in dirs) {
                var newX: Int64 = current.0 + dir.0
                var newY: Int64 = current.1 + dir.1
                if (newX >= 0 && newX < BOARD_SIZE.get(0) && newY >= 0 && newY < BOARD_SIZE.get(1)) {
                    var newPos: (Int64, Int64) = (newX, newY)
                    if (!contains(visited: visited, pos: newPos) && board.get(newX).get(newY) != " ") {
                        if (newPos == pos2 || board.get(newX).get(newY) == board.get(pos2.0).get(pos2.1)) {
                            return true
                        }
                        visited.add(newPos)
                        queue.add(newPos)
                    }
                }
            }
        }
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        var (x1, y1) = pos1
        var (x2, y2) = pos2
        board.get(x1).set(y1, " ")
        board.get(x2).set(y2, " ")
    }

    public func is_game_over(): Bool {
        for (var i: Int64 = 0; i < BOARD_SIZE.get(0); i++) {
            for (var j: Int64 = 0; j < BOARD_SIZE.get(1); j++) {
                if (board.get(i).get(j) != " ") {
                    return false
                }
            }
        }
        return true
    }
}

class Manacher {

    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        var left = center - diff
        var right = center + diff
        let chars = string.split(separator: "|")
        while left >= 0 && right < Int64(chars.count) && chars[Int64(left)] == chars[Int64(right)] {
            left -= 1
            right += 1
        }
        return (right - left - 1) / 2
    }

    public func palindromic_string(): String {
        if this.input_string.count == 0 {
            return ""
        }
        var processed = ""
        for c in this.input_string {
            processed += String(c) + "|"
        }
        processed.removeLast() // Remove the last '|'
        let chars = processed.split(separator: "|")
        var max_len = 0
        var center_pos = 0
        for i in 0..<chars.count {
            var len1 = this.palindromic_length(center: Int64(i), diff: 0, string: processed)
            var len2 = 0
            if i > 0 {
                len2 = this.palindromic_length(center: Int64(i - 1), diff: 1, string: processed)
            }
            let len = max(len1, len2)
            if len > max_len {
                max_len = len
                center_pos = i
            }
        }
        let start = center_pos - max_len + 1
        let end = center_pos + max_len
        var result = ""
        for i in start..<end {
            if i % 2 == 0 {
                let index = i / 2
                if index < this.input_string.count {
                    let charIndex = this.input_string.index(this.input_string.startIndex, offsetBy: index)
                    result += String(this.input_string[charIndex])
                }
            }
        }
        return result
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator {

    /*
    The class calculates precision, recall, F1 score, and accuracy based on predicted and true labels.
    */

    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        /*
        Initialize the number of all four samples to 0
        */
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        /*
        Update the number of all four samples(true_positives, false_positives, false_negatives, true_negatives)
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: None, change the number of corresponding samples
        >>> mc = MetricsCalculator()
        >>> mc.update(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        (this.true_positives, this.false_positives, this.false_negatives, this.true_negatives) = (1, 1, 1, 1)
        */
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
        for i in 0..<predicted_labels.size() {
            let predicted = predicted_labels.get(i)
            let true_label = true_labels.get(i)
            if predicted == 1 && true_label == 1 {
                this.true_positives += 1
            } else if predicted == 1 && true_label == 0 {
                this.false_positives += 1
            } else if predicted == 0 && true_label == 1 {
                this.false_negatives += 1
            } else if predicted == 0 && true_label == 0 {
                this.true_negatives += 1
            }
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate precision
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.precision(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        let total_positives = this.true_positives + this.false_positives
        if total_positives == 0 {
            return 0.0
        }
        return Float64(this.true_positives) / Float64(total_positives)
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.recall(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        let total_actual_positives = this.true_positives + this.false_negatives
        if total_actual_positives == 0 {
            return 0.0
        }
        return Float64(this.true_positives) / Float64(total_actual_positives)
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate f1 score, which is the harmonic mean of precision and recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.f1_score(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        let precision_val = this.precision(predicted_labels, true_labels)
        let recall_val = this.recall(predicted_labels, true_labels)
        if precision_val + recall_val == 0 {
            return 0.0
        }
        return 2.0 * precision_val * recall_val / (precision_val + recall_val)
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate accuracy
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.accuracy(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        let total_samples = predicted_labels.size()
        if total_samples == 0 {
            return 0.0
        }
        let correct_predictions = this.true_positives + this.true_negatives
        return Float64(correct_predictions) / Float64(total_samples)
    }
}

