class MetricsCalculator2 {

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        var results: ArrayList<(Float64, Float64)> = ArrayList()
        if let list = data as? ArrayList<Any> {
            for item in list {
                if let tuple = item as? (ArrayList<Int64>, Int64) {
                    let (predictions, totalGroundTruth) = tuple
                    var firstCorrectRank: Float64 = -1.0
                    for (rank, pred) in predictions.enumerate() {
                        if pred == 1 {
                            firstCorrectRank = Float64(rank + 1)
                            break
                        }
                    }
                    let reciprocalRank = firstCorrectRank > 0 ? 1.0 / firstCorrectRank : 0.0
                    results.add((reciprocalRank, reciprocalRank))
                }
            }
        } else if let tuple = data as? (ArrayList<Int64>, Int64) {
            let (predictions, totalGroundTruth) = tuple
            var firstCorrectRank: Float64 = -1.0
            for (rank, pred) in predictions.enumerate() {
                if pred == 1 {
                    firstCorrectRank = Float64(rank + 1)
                    break
                }
            }
            let reciprocalRank = firstCorrectRank > 0 ? 1.0 / firstCorrectRank : 0.0
            results.add((reciprocalRank, reciprocalRank))
        }

        var mrrValue: Float64 = 0.0
        var individualMrrs: ArrayList<Float64> = ArrayList()
        for item in results {
            mrrValue += item.0
            individualMrrs.add(item.1)
        }
        if !results.isEmpty {
            mrrValue /= Float64(results.size())
        }
        return (mrrValue, individualMrrs)
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        var results: ArrayList<Float64> = ArrayList()
        if let list = data as? ArrayList<Any> {
            for item in list {
                if let tuple = item as? (ArrayList<Int64>, Int64) {
                    let (predictions, totalGroundTruth) = tuple
                    var relevantRetrieved = 0
                    var apSum: Float64 = 0.0
                    for i in 0..<predictions.size() {
                        if predictions[i] == 1 {
                            relevantRetrieved += 1
                            var precisionAtI: Float64 = 0.0
                            var correctUpToNow = 0
                            for j in 0...i {
                                if predictions[j] == 1 {
                                    correctUpToNow += 1
                                }
                            }
                            precisionAtI = Float64(correctUpToNow) / Float64(i + 1)
                            apSum += precisionAtI
                        }
                    }
                    let relevantTotal = min(relevantRetrieved, totalGroundTruth)
                    let ap: Float64 = relevantTotal > 0 ? apSum / Float64(relevantTotal) : 0.0
                    results.add(ap)
                }
            }
        } else if let tuple = data as? (ArrayList<Int64>, Int64) {
            let (predictions, totalGroundTruth) = tuple
            var relevantRetrieved = 0
            var apSum: Float64 = 0.0
            for i in 0..<predictions.size() {
                if predictions[i] == 1 {
                    relevantRetrieved += 1
                    var precisionAtI: Float64 = 0.0
                    var correctUpToNow = 0
                    for j in 0...i {
                        if predictions[j] == 1 {
                            correctUpToNow += 1
                        }
                    }
                    precisionAtI = Float64(correctUpToNow) / Float64(i + 1)
                    apSum += precisionAtI
                }
            }
            let relevantTotal = min(relevantRetrieved, totalGroundTruth)
            let ap: Float64 = relevantTotal > 0 ? apSum / Float64(relevantTotal) : 0.0
            results.add(ap)
        }

        var mapValue: Float64 = 0.0
        var individualMaps: ArrayList<Float64> = ArrayList()
        for item in results {
            mapValue += item
            individualMaps.add(item)
        }
