import std.collection.ArrayList
import std.random.Random
import std.convert.Parsable

class MinesweeperGame {

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        var minePositions = ArrayList<ArrayList<Int64>>()
        var random = Random()

        while minePositions.size() < k {
            let x = random.nextInt(n)
            let y = random.nextInt(n)
            let pos = ArrayList<Int64>([x, y])
            if !minePositions.contains(pos) {
                minePositions.add(pos)
            }
        }

        for i in 0..<n {
            var row = ArrayList<String>()
            for j in 0..<n {
                row.add("0")
            }
            map.add(row)
        }

        for pos in minePositions {
            let x = pos[0]
            let y = pos[1]
            map[x][y] = "X"

            for dx in -1..2 {
                for dy in -1..2 {
                    let nx = x + dx
                    let ny = y + dy
                    if nx >= 0 && nx < n && ny >= 0 && ny < n && map[nx][ny] != "X" {
                        let num = (map[nx][ny] as Parsable<Int64>).parse()! + 1
                        map[nx][ny] = num.toString()
                    }
                }
            }
        }

        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        for i in 0..<n {
            var row = ArrayList<String>()
            for j in 0..<n {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for i in 0..<n {
            for j in 0..<n {
                if map[i][j] != "-" && this.minesweeper_map[i][j] != "X" {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if x < 0 || x >= n || y < 0 || y >= n {
            return this.player_map
        }

        if this.player_map[x][y] != "-" {
            return this.player_map
        }

        if this.minesweeper_map[x][y] == "X" {
            for i in 0..<n {
                for j in 0..<n {
                    if this.minesweeper_map[i][j] == "X" {
                        this.player_map[i][j] = "X"
                    }
                }
            }
            return false
        }

        let num = this.minesweeper_map[x][y]
        this.player_map[x][y] = num

        if num == "0" {
            for dx in -1..2 {
                for dy in -1..2 {
                    if dx == 0 && dy == 0 {
                        continue
                    }
                    let nx = x + dx
                    let ny = y + dy
                    if nx >= 0 && nx < n && ny >= 0 && ny < n {
                        self.sweep(nx, ny)
                    }
                }
            }
        }

        if this.check_won(this.player_map) {
            return true
        }
        return this.player_map
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.math.abs

class MovieBookingSystem {

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        let parsed_start = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let parsed_end = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")
        let seat_grid = ArrayList<ArrayList<Int64>>()
        for _ in 0..n {
            let row = ArrayList<Int64>()
            for _ in 0..n {
                row.add(0)
            }
            seat_grid.add(row)
        }
        let movie = HashMap<String, Any>()
        movie.put("name", name)
        movie.put("price", price)
        movie.put("start_time", parsed_start)
        movie.put("end_time", parsed_end)
        movie.put("seats", seat_grid)
        movies.add(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        for movie in movies {
            if movie.get("name") == name {
                let seats: ArrayList<ArrayList<Int64>> = movie.get("seats")
                let can_book = true
                for seat in seats_to_book {
                    let row = seat.get(0)
                    let col = seat.get(1)
                    if row < 0 || col < 0 || row >= seats.size() || col >= seats.get(0).size() || seats.get(row).get(col) == 1 {
                        can_book = false
                        break
                    }
                }
                if can_book {
                    for seat in seats_to_book {
                        let row = seat.get(0)
                        let col = seat.get(1)
                        seats.get(row).set(col, 1)
                    }
                    return "Booking success."
                } else {
                    return "Booking failed."
                }
            }
        }
        return "Movie not found."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        let start = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let end = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")
        let result = ArrayList<String>()
        for movie in movies {
            let movie_start = movie.get("start_time")
            let movie_end = movie.get("end_time")
            if (movie_start >= start && movie_start <= end) || 
               (movie_end >= start && movie_end <= end) || 
               (movie_start <= start && movie_end >= end) {
                result.add(movie.get("name"))
            }
        }
        return result
    }
}

import std.random.Random
import std.collection.ArrayList

class MusicPlayer {

    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        var index = -1
        for i in 0..<this.playlist.size() {
            if this.playlist[i] == song {
                index = i
                break
            }
        }
        if index != -1 {
            this.playlist.remove(index)
        }
    }

    public func play(): Option<String> {
        return this.current_song
    }

    public func stop(): Bool {
        if this.current_song != None {
            this.current_song = None
            return true
        }
        return false
    }

    public func switch_song(): Bool {
        if this.playlist.size() <= 0 {
            return false
        }
        var current_index = -1
        if this.current_song != None {
            for i in 0..<this.playlist.size() {
                if this.playlist[i] == this.current_song.get() {
                    current_index = i
                    break
                }
            }
        } else {
            current_index = -1
        }
        var next_index = (current_index + 1) % this.playlist.size()
        this.current_song = this.playlist[next_index]
        return true
    }

    public func previous_song(): Bool {
        if this.playlist.size() <= 0 {
            return false
        }
        var current_index = -1
        if this.current_song != None {
            for i in 0..<this.playlist.size() {
                if this.playlist[i] == this.current_song.get() {
                    current_index = i
                    break
                }
            }
        } else {
            current_index = -1
        }
        if current_index == -1 {
            this.current_song = this.playlist[this.playlist.size() - 1]
            return true
        }
        var prev_index = (current_index - 1 + this.playlist.size()) % this.playlist.size()
        this.current_song = this.playlist[prev_index]
        return true
    }

    public func set_volume(volume: Int64): Bool {
        if volume >= 0 && volume <= 100 {
            this.volume = volume
            return true
        }
        return false
    }

    public func shuffle(): Bool {
        if this.playlist.size() <= 0 {
            return false
        }
        var random = Random()
        for i in 0..<this.playlist.size() {
            var j = random.next_int(this.playlist.size())
            var temp = this.playlist[i]
            this.playlist[i] = this.playlist[j]
            this.playlist[j] = temp
        }
        return true
    }
}

import std.collection.ArrayList

class NLPDataProcessor {

    public func construct_stop_word_list(): ArrayList<String> {
        let stop_words = ArrayList<String>()
        stop_words.add("a")
        stop_words.add("an")
        stop_words.add("the")
        return stop_words
    }

    public func remove_stop_words(string_list: ArrayList<String>, stop_word_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        for sentence in string_list {
            let words = sentence.split(" ")
            let filtered_words = ArrayList<String>()
            for word in words {
                if !stop_word_list.contains(word) {
                    filtered_words.add(word)
                }
            }
            result.add(filtered_words)
        }
        return result
    }

    public func process(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let stop_words = construct_stop_word_list()
        return remove_stop_words(string_list, stop_words)
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        var words_list: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()
        for s in string_list {
            var cleaned: String = Regex.replace(input: s, pattern: "[^a-zA-Z ]", replacement: "")
            cleaned = cleaned.lower_case()
            var words: ArrayList<String> = ArrayList<String>()
            var split_words: ArrayList<String> = cleaned.split(" ")
            for word in split_words {
                if word.length() > 0 {
                    words.add(word)
                }
            }
            words_list.add(words)
        }
        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        var freq_map: HashMap<String, Int64> = HashMap<String, Int64>()
        for words in words_list {
            for word in words {
                if freq_map.contains_key(word) {
                    freq_map[word] = freq_map[word]! + 1
                } else {
                    freq_map[word] = 1
                }
            }
        }
        var sorted_items: ArrayList<[String, Int64]> = ArrayList<[String, Int64]>()
        for entry in freq_map.entries() {
            sorted_items.add([entry.key, entry.value])
        }
        sort(sorted_items, by: (a, b) => b[1] - a[1])
        var top_five: HashMap<String, Int64> = HashMap<String, Int64>()
        for i in 0..min(5, sorted_items.size()) {
            var item = sorted_items[i]
            top_five[item[0]] = item[1]
        }
        return top_five
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        var words_list: ArrayList<ArrayList<String>> = self.process_data(string_list: string_list)
        return self.calculate_word_frequency(words_list: words_list)
    }
}

import std.convert.Formattable
import std.convert.Parsable
import std.convert.RadixConvertible

class NumberConverter {

    /*
    The class allows to convert  decimal to binary, octal and hexadecimal repectively and contrarily
    */

    public static func decimal_to_binary(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to binary format.
        :param decimal_num: Int64, decimal number
        :return: String, the binary representation of an integer.
        >>> NumberConverter.decimal_to_binary(42423)
        '1010010110110111'
        */
        return decimal_num.to_string(radix: 2)
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        /*
        Convert a number from binary format to decimal format.
        :param binary_num: String, binary number
        :return: Int64, the decimal representation of binary number str.
        >>> NumberConverter.binary_to_decimal('1010010110110111')
        42423
        */
        return Int64.parse(binary_num, radix: 2)
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to octal format.
        :param decimal_num: Int64, decimal number
        :return: String, the octal representation of an integer.
        >>> NumberConverter.decimal_to_octal(42423)
        '122667'
        */
        return decimal_num.to_string(radix: 8)
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        /*
        Convert a number from octal format to decimal format.
        :param octal_num: String, octal number
        :return: Int64, the decimal representation of octal number str.
        >>> NumberConverter.octal_to_decimal('122667')
        42423
        */
        return Int64.parse(octal_num, radix: 8)
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to hex format.
        :param decimal_num: Int64, decimal number
        :return hex_num: String, the hex representation of an integer.
        >>> NumberConverter.decimal_to_hex(42423)
        'a5b7'
        */
        return decimal_num.to_string(radix: 16)
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        /*
        Convert a number from hex format to decimal format.
        :param hex_num: String, hex num
        :return: Int64, the decimal representation of hex number str.
        >>> NumberConverter.hex_to_decimal('a5b7')
        42423
        */
        return Int64.parse(hex_num, radix: 16)
    }
}

import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    /*
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    */

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        /*
        Initialize NumberWordFormatter object.
        */
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        /*
        Converts a number into words format
        :param x: Option<String>, the number to be converted into words format
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        if x.isNone() {
            return "ZERO ONLY"
        }
        return this.format_string(x.get())
    }

    public func format_string(x: String): String {
        /*
        Converts a string representation of a number into words format
        :param x: String, the string representation of a number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        let s = x.split('.')
        let integerPart = s[0]
        let decimalPart = s.length > 1 ? s[1] : ""
        let words = this.trans(integerPart)
        var result = ""
        if !words.isEmpty() {
            result = words + " ONLY"
        } else {
            result = "ZERO ONLY"
        }
        if !decimalPart.isEmpty() {
            let decimalWords = this.trans(decimalPart)
            if !decimalWords.isEmpty() {
                result += " AND POINT " + decimalWords
            }
        }
        return result
    }

    public func trans_two(s: String): String {
        /*
        Converts a two-digit number into words format
        :param s: String, the two-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        */
        let num = s.toInt64()
        if num < 10 {
            return this.NUMBER[num.toInt()] ?? ""
        } else if num < 20 {
            return this.NUMBER_TEEN[num.toInt() - 10]
        } else {
            let ten = this.NUMBER_TEN[num.toInt() / 10 - 1]
            let one = this.NUMBER[num.toInt() % 10]
            if num.toInt() % 10 != 0 {
                return ten + " " + one
            } else {
                return ten
            }
        }
    }

    public func trans_three(s: String): String {
        /*
        Converts a three-digit number into words format
        :param s: String, the three-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        */
        let num = s.toInt64()
        let hundred = num.toInt() / 100
        let remainder = num.toInt() % 100
        var result = ""
        if hundred > 0 {
            result += this.NUMBER[hundred] + " HUNDRED"
        }
        let twoWords = this.trans_two(remainder.toString())
        if remainder > 0 {
            if hundred > 0 {
                result += " AND "
            }
            result += twoWords
        }
        return result
    }

    public func parse_more(i: Int64): String {
        /*
        Parses the thousand/million/billion suffix based on the index
        :param i: Int64, the index representing the magnitude (thousand, million, billion)
        :return: String, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        */
        return this.NUMBER_MORE[i.toInt()]
    }

    public func trans(s: String): String {
        if s.isEmpty() {
            return ""
        }
        let num = s.toInt64()
        if num == 0 {
            return ""
        }
        let sLength = s.length()
        let units = [1000000000, 1000000, 1000, 1].reversed()
        var res = ""
        for (i, unit) in units.enumerated() {
            if num >= unit {
                let quotient = num / unit
                let remaining = num % unit
                let quotientStr = quotient.toString()
                var quotientWords = ""
                if quotientStr.length() == 3 {
                    quotientWords = this.trans_three(quotientStr)
                } else if quotientStr.length() == 2 {
                    quotientWords = this.trans_two(quotientStr)
                } else if quotientStr.length() == 1 {
                    quotientWords = this.NUMBER[quotientStr.toInt()] ?? ""
                }
                let suffix = this.parse_more(i.toInt64())
                if !quotientWords.isEmpty() {
                    res += quotientWords + " " + suffix + " "
                }
                num = remaining
            }
        }
        if num > 0 {
            let remainingStr = num.toString()
            var remainingWords = ""
            if remainingStr.length() == 3 {
                remainingWords = this.trans_three(remainingStr)
            } else if remainingStr.length() == 2 {
                remainingWords = this.trans_two(remainingStr)
            } else if remainingStr.length() == 1 {
                remainingWords = this.NUMBER[remainingStr.toInt()] ?? ""
            }
            res += remainingWords
        }
        return res.trim()
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible
import std.text.StringBuilder

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        var result = StringBuilder()
        var i = 0
        while i < string.length {
            if string[i] == '&' && i + 2 < string.length && string[i + 1] == '#' {
                var j = i + 2
                var numeric = false
                var hex = false
                if j < string.length && string[j] == 'x' {
                    hex = true
                    j += 1
                }
                var numStr = ""
                while j < string.length && (string[j].is_digit() || (hex && is_hex_char(char: string[j]))) {
                    numStr += string[j]
                    j += 1
                }
                if j < string.length && string[j] == ';' {
                    var num = 0
                    if hex {
                        num = numStr.to_int(16) ?? 0
                    } else {
                        num = numStr.to_int(10) ?? 0
                    }
                    result.append(Rune(num))
                    i = j + 1
                    continue
                }
            }
            result.append(string[i])
            i += 1
        }
        return result.to_string()
    }

    public static func is_hex_char(char: Rune): Bool {
        return (char >= r'0' && char <= r'9') || 
               (char >= r'a' && char <= r'f') || 
               (char >= r'A' && char <= r'F')
    }
}

