class SQLQueryBuilder {

    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "SELECT " + String.join(", ", columns.toArray()) + " FROM " + table
        if where_condition.isSome() {
            var conditions = ArrayList<String>()
            for (key, value) in where_condition.unwrap().entries() {
                conditions.add(key + "='" + value + "'")
            }
            query += " WHERE " + String.join(" AND ", conditions.toArray())
        }
        return query
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        var columns = ArrayList<String>()
        var values = ArrayList<String>()
        for (key, value) in data.entries() {
            columns.add(key)
            values.add("'" + value + "'")
        }
        return "INSERT INTO " + table + " (" + String.join(", ", columns.toArray()) + ") VALUES (" + String.join(", ", values.toArray()) + ")"
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "DELETE FROM " + table
        if where_condition.isSome() {
