        }
        return query
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        var sorted = data.clone()
        sort(sorted)
        var n = sorted.size()
        if n % 2 == 1 {
            return Float64(sorted[n/2])
        } else {
            return (Float64(sorted[n/2 - 1]) + Float64(sorted[n/2])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        var freqMap = HashMap<Int64, Int64>()
        for num in data {
            var count = freqMap.get(num).unwrap_or(0)
            freqMap[num] = count + 1
        }
        var modes = ArrayList<Int64>()
        var maxCount: Int64 = 0
        for (num, count) in freqMap {
            if count > maxCount {
                maxCount = count
                modes = ArrayList<Int64>([num])
            } else if count == maxCount {
                modes.add(num)
            }
        }
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if x.size() != y.size() || x.size() == 0 {
            return Option.None
        }

        var sumX: Int64 = 0
        var sumY: Int64 = 0
        var sumXY: Int64 = 0
        var sumX2: Int64 = 0
        var sumY2: Int64 = 0
        for i in 0..x.size() {
            var xi = x[i]
            var yi = y[i]
            sumX += xi
            sumY += yi
            sumXY += xi * yi
            sumX2 += xi * xi
            sumY2 += yi * yi
        }

        var n = Float64(x.size())
        var numerator = Float64(n * sumXY - sumX * sumY)
        var denominatorX = sqrt(Float64(n * sumX2 - sumX * sumX))
        var denominatorY = sqrt(Float64(n * sumY2 - sumY * sumY))

        if denominatorX == 0 || denominatorY == 0 {
            return Option.None
        }

        return Option.Some(numerator / (denominatorX * denominatorY))
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if data.size() == 0 {
            return Option.None
        }
        var sum: Int64 = 0
        for num in data {
            sum += num
        }
        return Option.Some(Float64(sum) / Float64(data.size()))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        var n = data.size()
        if n == 0 {
            return ArrayList<ArrayList<Float64>>()
        }
        var result = ArrayList<ArrayList<Float64>>()
        for i in 0..n {
            var row = ArrayList<Float64>()
            for j in 0..n {
                if i == j {
                    row.add(1.0)
                } else {
                    match correlation(data[i], data[j]) {
                        Option.Some(corr) => row.add(corr),
                        Option.None => row.add(0.0)
                    }
                }
            }
            result.add(row)
        }
        return result
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        match mean(data) {
            Option.Some(m) => {
                var sumSqDiff: Float64 = 0.0
                for num in data {
                    sumSqDiff += (Float64(num) - m) * (Float64(num) - m)
                }
                return Option.Some(sqrt(sumSqDiff / Float64(data.size())))
            },
            Option.None => Option.None
        }
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        match mean(data) {
            Option.Some(m) => {
                match standard_deviation(data) {
                    Option.Some(stdDev) => {
                        if stdDev == 0.0 {
                            return Option.None
                        }
                        var zScores = ArrayList<Float64>()
                        for num in data {
                            zScores.add((Float64(num) - m) / stdDev)
                        }
                        return Option.Some(zScores)
                    },
                    Option.None => Option.None
                }
            },
            Option.None => Option.None
        }
    }
}

import std.collection.ArrayList
import std.collection.HashMap
