    }
}

class WeatherSystem {

    var temperature: Float64
    var weather: String
    var city: String
    var weather_list: HashMap<String, Weather>

    public init(city: String) {
        this.temperature = Float64.NaN
        this.weather = ""
        this.city = city
        this.weather_list = HashMap<String, Weather>()
    }

    public func query(weather_list: HashMap<String, Weather>, tmp_units!: String = 'celsius'): Option<(Float64, String)> {
        let weather_data = weather_list.get(this.city)
        if weather_data == null {
            return Option.none<(Float64, String)>()
        }
        let temp = weather_data.temperature
        let weather = weather_data.weather
        if tmp_units == 'fahrenheit' && weather_data.temperature_units == 'celsius' {
            return Option.some<(Float64, String)>((this.celsius_to_fahrenheit(celsius: temp), weather))
        } else if tmp_units == 'celsius' && weather_data.temperature_units == 'fahrenheit' {
            return Option.some<(Float64, String)>((this.fahrenheit_to_celsius(fahrenheit: temp), weather))
        }
        return Option.some<(Float64, String)>((temp, weather))
    }

    public func set_city(city: String): Unit {
        this.city = city
        return Unit
    }

    public func celsius_to_fahrenheit(celsius: Float64): Float64 {
        return (celsius * 9.0 / 5.0) + 32.0
    }

    public func fahrenheit_to_celsius(fahrenheit: Float64): Float64 {
        return (fahrenheit - 32.0) * 5.0 / 9.0
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.text.StringTokenizer
import std.math.pow

class Words2Numbers {

    let numwords: HashMap<String, (Int64, Int64)>
    let units: ArrayList<String>
    let tens: ArrayList<String>
    let scales: ArrayList<String>
    let ordinal_words: HashMap<String, Int64>
    let ordinal_endings: ArrayList<(String, String)>

    public init() {
        this.numwords = HashMap<String, (Int64, Int64)>()
        this.units = ArrayList<String>(["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"])
        this.tens = ArrayList<String>(["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"])
        this.scales = ArrayList<String>(["hundred", "thousand", "million", "billion", "trillion"])

        this.numwords["and"] = (1, 0)
        for (idx in 0..<this.units.size) {
            this.numwords[this.units[idx]] = (1, Int64(idx))
        }
        for (idx in 2..<this.tens.size) {
            this.numwords[this.tens[idx]] = (1, Int64(idx * 10))
        }
        for (idx in 0..<this.scales.size) {
            let scale = if idx == 0 then 100 else Int64(pow(10, (idx + 2) * 3))
            this.numwords[this.scales[idx]] = (scale, 0)
        }

        this.ordinal_words = HashMap<String, Int64>()
        this.ordinal_words["first"] = 1
        this.ordinal_words["second"] = 2
        this.ordinal_words["third"] = 3
        this.ordinal_words["fifth"] = 5
        this.ordinal_words["eighth"] = 8
        this.ordinal_words["ninth"] = 9
        this.ordinal_words["twelfth"] = 12
        this.ordinal_endings = ArrayList<(String, String)>()
        this.ordinal_endings.add(("ieth", "y"))
        this.ordinal_endings.add(("th", ""))
    }

    public func text2int(textnum: String): String {
        if (this.is_valid_input(textnum: textnum) == false) {
            return "0"
        }
        let current = Int64(0)
        let result = Int64(0)
        let words = StringTokenizer(textnum, " \t-")
        while (words.hasMoreTokens()) {
            let word = words.nextToken().lowercase()
            if (this.numwords.containsKey(word)) {
                let (scale, increment) = this.numwords[word]!
                current = current * scale + increment
            } else if (word == "and") {
                continue
            } else {
                let foundOrdinal = false
                for (ending in this.ordinal_endings) {
                    if (word.endsWith(ending.0)) {
                        let base = word.substring(0, word.length() - ending.0.length()) + ending.1
                        if (this.numwords.containsKey(base)) {
                            let (scale, increment) = this.numwords[base]!
                            current = current * scale + increment
                            foundOrdinal = true
                            break
                        }
                    }
                }
                if (!foundOrdinal && this.ordinal_words.containsKey(word)) {
                    current = this.ordinal_words[word]!
                } else {
                    return "0"
                }
            }
            if (this.numwords.containsKey(word) && this.numwords[word]!.0 != 1) {
                result = result + current
                current = Int64(0)
            }
        }
        return (result + current).toString()
    }

    public func is_valid_input(textnum: String): Bool {
        let words = StringTokenizer(textnum, " \t-")
        while (words.hasMoreTokens()) {
            let word = words.nextToken().lowercase()
            if (this.numwords.containsKey(word)) {
                continue
            } else if (word == "and") {
                continue
            } else {
                var validOrdinal = false
                for (ending in this.ordinal_endings) {
                    if (word.endsWith(ending.0)) {
                        let base = word.substring(0, word.length() - ending.0.length()) + ending.1
                        if (this.numwords.containsKey(base)) {
                            validOrdinal = true
                            break
                        }
                    }
                }
                if (!validOrdinal && !this.ordinal_words.containsKey(word)) {
                    return false
                }
            }
        }
        return true
    }
}
